<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Andesite Hosting - Console</title>
    <style>
        :root {
            --bg-dark: #121214;
            --bg-panel: #1c1c1f;
            --bg-input: #18181a;
            --border-color: #2e2e33;
            --text-main: #e0e0e2;
            --text-muted: #8b8b90;
            --accent-orange: #e67e22;
            --accent-orange-hover: #d35400;
            --status-green: #2ecc71;
            --log-info: #9ca3af;
            --log-chat: #2ecc71; /* Green for chat lines */
            --font-mono: 'Consolas', 'Monaco', 'Courier New', monospace;
            --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            background-color: var(--bg-dark);
            color: var(--text-main);
            font-family: var(--font-sans);
            height: 100vh;
            display: flex;
            flex-direction: column;
            overflow: hidden;
        }

        /* Header */
        header {
            height: 60px;
            background-color: var(--bg-panel);
            border-bottom: 1px solid var(--border-color);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 20px;
            flex-shrink: 0;
        }

        .brand {
            display: flex;
            align-items: center;
            gap: 12px;
            font-weight: 600;
            font-size: 16px;
            color: #fff;
        }

        .logo-icon {
            width: 28px;
            height: 28px;
            background: linear-gradient(135deg, #555, #333);
            border-radius: 6px;
            display: grid;
            place-items: center;
            border: 1px solid #666;
        }

        .logo-icon::after {
            content: '';
            width: 14px;
            height: 14px;
            background-color: var(--accent-orange);
            border-radius: 3px;
            opacity: 0.8;
        }

        .header-actions {
            display: flex;
            align-items: center;
            gap: 15px;
        }

        .btn-primary {
            background-color: var(--accent-orange);
            color: white;
            border: none;
            padding: 8px 16px;
            border-radius: 6px;
            font-weight: 600;
            cursor: pointer;
            font-size: 13px;
            transition: background 0.2s;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .btn-primary:hover {
            background-color: var(--accent-orange-hover);
        }

        .avatar {
            width: 32px;
            height: 32px;
            background-color: #d4a373; /* Skin tone */
            border-radius: 4px; /* Minecraft square-ish avatar */
            border: 2px solid #444;
            image-rendering: pixelated;
            overflow: hidden;
        }

        .avatar img { width: 100%; height: 100%; object-fit: cover; }

        /* Layout Container */
        .layout-container {
            display: flex;
            flex: 1;
            overflow: hidden;
        }

        /* Sidebar */
        aside {
            width: 260px;
            background-color: var(--bg-panel);
            border-right: 1px solid var(--border-color);
            display: flex;
            flex-direction: column;
            padding: 20px;
            flex-shrink: 0;
        }

        .nav-item {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 10px 12px;
            color: var(--text-muted);
            text-decoration: none;
            border-radius: 6px;
            margin-bottom: 5px;
            font-size: 14px;
            font-weight: 500;
            transition: all 0.2s;
        }

        .nav-item:hover {
            background-color: rgba(255,255,255,0.05);
            color: #fff;
        }

        .nav-section-title {
            font-size: 11px;
            text-transform: uppercase;
            letter-spacing: 1px;
            color: var(--text-muted);
            margin-top: 25px;
            margin-bottom: 12px;
            font-weight: 700;
        }

        .server-list {
            list-style: none;
        }

        .server-item {
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 10px 12px;
            border-radius: 6px;
            cursor: pointer;
            margin-bottom: 4px;
            position: relative;
        }

        .server-item.active {
            background-color: rgba(230, 126, 34, 0.1); /* Very subtle orange tint */
            border-left: 3px solid var(--accent-orange); /* Visual indicator for active tab */
        }

        .server-info {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .status-dot {
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background-color: #555;
        }

        .status-dot.online {
            background-color: var(--status-green);
            box-shadow: 0 0 6px var(--status-green);
        }

        .server-name {
            font-weight: 600;
            font-size: 13px;
            color: #eee;
        }

        .server-tag {
            font-size: 10px;
            background: #333;
            padding: 2px 6px;
            border-radius: 4px;
            color: #aaa;
        }

        /* Main Content */
        main {
            flex: 1;
            display: flex;
            flex-direction: column;
            background-color: var(--bg-dark);
            position: relative;
        }

        /* Console Output Area */
        .console-output {
            flex: 1;
            overflow-y: auto;
            padding: 15px 20px;
            font-family: var(--font-mono);
            font-size: 13px;
            line-height: 1.6;
            scroll-behavior: smooth;
        }

        /* Custom Scrollbar */
        .console-output::-webkit-scrollbar {
            width: 8px;
        }
        .console-output::-webkit-scrollbar-track {
            background: var(--bg-dark);
        }
        .console-output::-webkit-scrollbar-thumb {
            background: #333;
            border-radius: 4px;
        }

        .log-line {
            white-space: pre-wrap;
            word-break: break-all;
            margin-bottom: 2px;
            color: var(--log-info);
        }

        .log-time {
            color: #666;
        }

        .log-level-info {
            color: #9ca3af; /* Grayish */
        }

        .log-level-server {
            color: #f0f0f0; /* White/Gray for [Server] */
            font-weight: bold;
        }

        .log-brand {
            color: var(--accent-orange); /* Orange accent for brand check */
        }

        .log-chat-text {
            color: var(--log-chat); /* Green for chat/say lines as requested */
        }

        /* Input Area */
        .console-input-area {
            background-color: var(--bg-panel);
            border-top: 1px solid var(--border-color);
            padding: 15px 20px;
            flex-shrink: 0;
        }

        .input-wrapper {
            display: flex;
            gap: 10px;
            margin-bottom: 10px;
        }

        .prompt-symbol {
            color: var(--accent-orange);
            font-family: var(--font-mono);
            font-weight: bold;
            font-size: 18px;
            line-height: 40px; /* Align with input height */
            padding-right: 5px;
        }

        .command-input {
            flex: 1;
            background-color: var(--bg-input);
            border: 1px solid var(--accent-orange); /* Orange border focus state simulation */
            color: #fff;
            padding: 0 15px;
            font-family: var(--font-mono);
            font-size: 14px;
            border-radius: 6px;
            outline: none;
            height: 42px;
        }

        .command-input::placeholder {
            color: #666;
        }

        .send-btn {
            width: 42px;
            height: 42px;
            background-color: var(--accent-orange);
            border: none;
            border-radius: 6px;
            color: white;
            cursor: pointer;
            display: flex;
            align-items: center;
            justify-content: center;
            transition: background 0.2s;
        }

        .send-btn:hover {
            background-color: var(--accent-orange-hover);
        }

        .shortcuts {
            display: flex;
            gap: 10px;
            flex-wrap: wrap;
        }

        .shortcut-chip {
            font-family: var(--font-mono);
            font-size: 11px;
            color: var(--text-muted);
            background: #252528;
            padding: 4px 10px;
            border-radius: 12px;
            cursor: pointer;
            border: 1px solid transparent;
            transition: all 0.2s;
        }

        .shortcut-chip:hover {
            border-color: var(--border-color);
            color: #ddd;
        }

        /* Footer Status Bar (Inside Sidebar bottom or Main bottom? Screenshot shows it in sidebar area) */
        .sidebar-footer {
            margin-top: auto;
            padding-top: 20px;
            border-top: 1px solid var(--border-color);
            font-size: 12px;
            color: var(--text-muted);
        }

        .node-status-row {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 8px;
